+               int64_t layer_lo = 0, int64_t layer_hi = 0,
+               const std::array<int64_t, 18>* geometry = nullptr) const {
         Match best;
         for (size_t i = entries_.size(); i-- > 0;) {
             const auto& e = entries_[i];
